document.querySelectorAll('[data-lab="G09-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const tau=root.querySelector('[data-tau]'),spacing=root.querySelector('[data-spacing]'),en=root.dataset.language==='en';function draw(){const tc=+tau.value,dt=+spacing.value,n=Math.round(500/dt);let g=1;for(let k=1;k<n;k++)g+=2*(1-k/n)*(tc===0?0:Math.exp(-k*dt/tc));const ne=n/g,se=.01*Math.sqrt(g/n),X=t=>85+t*7.6,Y=c=>320-c*230;root.querySelector('[data-tau-value]').textContent=tc===0?(en?'0 (independent limit)':'0（独立极限）'):tc+' ps';let s='<rect width="960" height="400" fill="#f6f4ed"/><path d="M85 80V320H845" stroke="#78928e" fill="none"/>';for(let t of [0,20,40,60,80,100])s+=`<text x="${X(t)}" y="350" text-anchor="middle" font-size="22">${t}</text>`;for(let c of [0,.5,1])s+=`<text x="70" y="${Y(c)+8}" text-anchor="end" font-size="22">${c}</text>`;s+='<text x="85" y="45" font-size="24">C(k)</text><text x="710" y="388" font-size="22">'+(en?'Lag / ps':'时间间隔 / ps')+'</text>';let points=[];for(let k=0;k<=Math.floor(100/dt);k++){let t=k*dt,c=k===0?1:tc===0?0:Math.exp(-t/tc);points.push(X(t)+','+Y(c));}s+=`<polyline points="${points.join(' ')}" stroke="#167d84" stroke-width="3" fill="none"/>`;root.querySelector('[data-plot]').innerHTML=s;root.querySelector('[data-feedback]').textContent=`N = ${n}; gN = ${g.toFixed(5)}; Neff = ${ne.toFixed(5)}; SE = ${se.toFixed(8)} nm. `+(en?'The observation window and physical correlation time stay fixed when spacing changes.':'改变保存间隔时，观察范围与给定的物理相关时间保持不变。');}tau.addEventListener('input',draw);spacing.addEventListener('change',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{tau.value='20';spacing.value='1';draw();});draw();});